import {watcherCommands} from '../examples.js';
import {applySceneCommand} from '../schema.js';
// Retire only unchanged tracks generated by the pre-controller example. Custom
// authored tracks remain active; an explicit new key can override a retired one.
export async function watcherPlacementCommands(scene){
 const reference={assets:[],scene3d:null};for(const c of await watcherCommands())applySceneCommand(reference,c);
 const signature=t=>JSON.stringify({...t,controllerOwned:undefined});
 const commands=[];for(const clip of scene.clips){const original=reference.scene3d.clips.find(c=>c.id===clip.id);if(!original)continue;const tracks=clip.tracks.map(t=>original.tracks.some(old=>signature(t)===signature(old))?{...t,controllerOwned:true}:t);commands.push({op:'scene3d.clip.update',id:clip.id,values:{tracks}});}
 return [...commands,{op:'scene3d.settings',values:{watcherPlacementVersion:1}}];
}
